    public static string[] Run() => [
        Check("正常通知", () => { var s = new Subject(); int value = 0; s.Subscribe(v => value = v); s.Publish(7); return value == 7; }),
        Check("取消后不再通知", () => { var s = new Subject(); int n = 0; Action<int> a = _ => n++; s.Subscribe(a); s.Publish(1); s.Unsubscribe(a); s.Publish(2); return n == 1; }),
        Check("其他观察者继续工作", () => { var s = new Subject(); int a = 0, b = 0; Action<int> one = _ => a++; s.Subscribe(one); s.Subscribe(_ => b++); s.Unsubscribe(one); s.Publish(1); return a == 0 && b == 1; })
    ];

    private static string Check(string name, Func<bool> test)
    {
        try { return (test() ? "+" : "-") + name; }
        catch { return "-" + name; }
    }
}

