exercises.solution:
using System.Collections.Generic;
public sealed class History
{
    private readonly Stack<string> undo = new();
    private readonly Stack<string> redo = new();
    public string Text { get; private set; } = "";
    public void Append(string text) { undo.Push(Text); Text += text; redo.Clear(); }
    public void Undo() { var prior = undo.Pop(); redo.Push(Text); Text = prior; }
    public void Redo() { var next = redo.Pop(); undo.Push(Text); Text = next; }
}

