exercises.solution:
using System;
public enum Status { New, Paid, Cancelled }
public sealed class Order
{
    public Status State { get; private set; } = Status.New;
    public void Pay() { EnsureNew(); State = Status.Paid; }
    public void Cancel() { EnsureNew(); State = Status.Cancelled; }
    private void EnsureNew() { if (State != Status.New) throw new InvalidOperationException(); }
}

