using System;
public static class Price
{
    public static decimal Total(decimal subtotal)
    {
        if (subtotal < 0) throw new ArgumentOutOfRangeException(nameof(subtotal));
        return subtotal >= 300 ? subtotal - 40 : subtotal;
    }
}

